template:
{%- set django = value.get("engine") == "django" -%}
<div class="studio-editor" data-studio-editor-item data-studio-kind="component" data-studio-mode="view">
<p class="studio-editor-meta">{{ value.get("engine") or "" }} · {{ value.get("mode") or "" }}</p>
{%- if django %}
<p class="studio-note">This component uses the Django engine, which the studio does not edit: it is shown read-only. Edit it through the API or the bootstrap studio.</p>
{%- endif %}
<textarea class="studio-code" readonly rows="20" spellcheck="false" aria-label="Template of {{ value.name }} (read-only)">
{{ value.get("template") or "" }}</textarea>
</div>
